import{t as e}from"./api-CVHbzLQj.js";var t={getAllShops:async()=>(await e.get(`/search`)).data,searchShops:async t=>(await e.get(`/search?keyword=${encodeURIComponent(t)}`)).data,getNearbyShops:async(t,n,r=5)=>(await e.get(`/search?lat=${t}&long=${n}&radius=${r}`)).data,getMyShops:async()=>(await e.get(`/shop/my-shops`)).data,createShop:async t=>(await e.post(`/shop`,t,{timeout:12e4})).data,getShopDetails:async t=>(await e.get(`/shop/${t}`)).data,getShopServices:async t=>(await e.get(`/service/shop/${t}`)).data,getShopStaff:async t=>(await e.get(`/shop/${t}/staff`)).data,getShopReviews:async t=>(await e.get(`/review/shop/${t}`)).data,updateShop:async(t,n)=>(await e.put(`/shop/${t}`,n,{timeout:12e4})).data,getShopSlots:async(t,n,r)=>{let i=`/shop/${t}/slots?date=${n}`;return r&&(i+=`&barberId=${r}`),(await e.get(i)).data}};export{t};